using UnityEngine; using UnityEngine.UI; using System.Collections.Generic;
namespace Blockverse {
 public sealed class GameController:MonoBehaviour {
  [SerializeField] private RectTransform boardRoot,trayRoot; [SerializeField] private Text scoreLabel,goalLabel,hintLabel; [SerializeField] private Button restartButton;
  private BoardModel board; private int score,level=1,randomSeed,piecesUsed,bestScore,coins; private LevelConfig config; private readonly List<PieceDragView> trayPieces=new List<PieceDragView>();
  private void Start(){bestScore=PlayerPrefs.GetInt("blockverse_best_score",0);coins=PlayerPrefs.GetInt("blockverse_coins",0);level=PlayerPrefs.GetInt("blockverse_level",1);if(restartButton!=null)restartButton.onClick.AddListener(StartLevel);StartLevel();}
  public void StartLevel(){config=LevelGenerator.Generate(level);board=new BoardModel(config.BoardSize,config.BoardSize);score=0;piecesUsed=0;randomSeed=config.Seed;PlaceLevelObstacles();RefreshLabels();BuildBoard();GenerateTray();}
  private void BuildBoard(){if(boardRoot==null)return;foreach(Transform c in boardRoot)Destroy(c.gameObject);var grid=boardRoot.GetComponent<GridLayoutGroup>();if(grid==null)grid=boardRoot.gameObject.AddComponent<GridLayoutGroup>();grid.constraint=GridLayoutGroup.Constraint.FixedColumnCount;grid.constraintCount=config.BoardSize;grid.spacing=new Vector2(5,5);float cell=Mathf.Floor((boardRoot.rect.width-5f*(config.BoardSize-1))/config.BoardSize);grid.cellSize=new Vector2(cell,cell);for(int y=0;y<config.BoardSize;y++)for(int x=0;x<config.BoardSize;x++){var tile=new GameObject($"Cell_{x}_{y}",typeof(RectTransform),typeof(Image));tile.transform.SetParent(boardRoot,false);tile.GetComponent<Image>().color=new Color(.13f,.17f,.24f,1);}RefreshBoardVisuals();}
  private void PlaceLevelObstacles(){if(config.ObstacleCount<=0)return;var r=new System.Random(config.Seed^0x5F3759DF);int placed=0,attempts=config.ObstacleCount*12;while(placed<config.ObstacleCount&&attempts-->0){int x=r.Next(board.Width),y=r.Next(board.Height);if(board.GetCell(x,y)!=CellType.Empty)continue;board.SetObstacle(x,y,r.Next(2)==0?CellType.Stone:CellType.Ice);placed++;}}
  private void GenerateTray(){if(trayRoot==null)return;foreach(Transform c in trayRoot)Destroy(c.gameObject);trayPieces.Clear();piecesUsed=0;var r=new System.Random(randomSeed++);for(int i=0;i<3;i++){var go=new GameObject($"Piece_{i}",typeof(RectTransform),typeof(PieceDragView));go.transform.SetParent(trayRoot,false);var view=go.GetComponent<PieceDragView>();view.Initialize(this,PieceLibrary.CreateRandom(r),trayRoot);trayPieces.Add(view);}if(hintLabel!=null)hintLabel.text="DRAG A BLOCK ONTO THE BOARD";CheckGameOver();}
  public bool TryDrop(PieceDefinition piece,Vector2 screen,Camera eventCamera){if(boardRoot==null||board==null)return false;if(!RectTransformUtility.ScreenPointToLocalPointInRectangle(boardRoot,screen,eventCamera,out Vector2 local))return false;var grid=boardRoot.GetComponent<GridLayoutGroup>();float px=grid.cellSize.x+grid.spacing.x,py=grid.cellSize.y+grid.spacing.y;int x=Mathf.FloorToInt((local.x-boardRoot.rect.xMin)/px),y=Mathf.FloorToInt((boardRoot.rect.yMax-local.y)/py);x-=piece.Shape.GetLength(1)/2;y-=piece.Shape.GetLength(0)/2;if(!board.TryPlace(piece.Shape,x,y)){if(hintLabel!=null)hintLabel.text="NOT A VALID POSITION — TRY AGAIN";return false;}
   int cx=x+piece.Shape.GetLength(1)/2,cy=y+piece.Shape.GetLength(0)/2,affected=0;switch(piece.Special){case SpecialPieceType.Bomb:affected=board.Blast(cx,cy);break;case SpecialPieceType.Rainbow:affected=board.ClearRow(cy);break;case SpecialPieceType.Lightning:affected=board.ClearColumn(cx);break;}
   int cleared=board.ClearCompletedLines();score+=CountCells(piece.Shape)*10+cleared*config.BoardSize*10+affected*5;if(score>bestScore){bestScore=score;PlayerPrefs.SetInt("blockverse_best_score",bestScore);}if(cleared>0){coins+=cleared*2;PlayerPrefs.SetInt("blockverse_coins",coins);}PlayerPrefs.Save();RefreshBoardVisuals();RefreshLabels();if(hintLabel!=null)hintLabel.text=(cleared>0?$"NICE! {cleared} LINE(S) CLEARED":"GOOD MOVE!")+(piece.Special==SpecialPieceType.None?"":$" — {piece.Special.ToString().ToUpperInvariant()}");return true;}
  private int CountCells(bool[,] s){int n=0;foreach(bool b in s)if(b)n++;return n;}
  public void ConsumePiece(PieceDragView p){if(p==null)return;p.gameObject.SetActive(false);piecesUsed++;if(piecesUsed>=3)GenerateTray();else CheckGameOver();}
  private void CheckGameOver(){foreach(var p in trayPieces){if(p==null||!p.gameObject.activeSelf)continue;if(HasAnyPlacement(p.Definition.Shape))return;}if(trayPieces.Count==0)return;if(hintLabel!=null)hintLabel.text="NO MORE MOVES — RESTART TO TRY AGAIN";foreach(var p in trayPieces)if(p!=null)p.enabled=false;}
  private bool HasAnyPlacement(bool[,] s){for(int y=0;y<board.Height;y++)for(int x=0;x<board.Width;x++)if(board.CanPlace(s,x,y))return true;return false;}
  private void RefreshBoardVisuals(){if(boardRoot==null||board==null)return;int i=0;foreach(Transform child in boardRoot){int x=i%board.Width,y=i/board.Width;var image=child.GetComponent<Image>();switch(board.GetCell(x,y)){case CellType.Normal:image.color=new Color(.24f,.63f,1);break;case CellType.Stone:image.color=new Color(.38f,.4f,.45f);break;case CellType.Ice:image.color=new Color(.35f,.85f,1);break;case CellType.CrackedIce:image.color=new Color(.2f,.58f,.7f);break;default:image.color=new Color(.13f,.17f,.24f);break;}i++;}}
  private void RefreshLabels(){if(scoreLabel!=null)scoreLabel.text=$"SCORE  {score:N0}";if(goalLabel!=null)goalLabel.text=$"LEVEL {level} • {config?.Goal.ToString().ToUpperInvariant()} • BEST {bestScore:N0} • COINS {coins}";}
 }
}